<?php $totalUsers=(int)$stats['usuarios'];$teachers=(int)$stats['docentes'];$tests=(int)$stats['tests'];$tabulators=(int)$stats['tabuladores'];$adminUsers=max(0,$totalUsers-$teachers);$totalResources=$tests+$tabulators;$teacherPct=$totalUsers?round($teachers/$totalUsers*100):0;$testPct=$totalResources?round($tests/$totalResources*100):0;$resourcesPerTeacher=$teachers?round($totalResources/$teachers,1):0; ?><main class="content container-fluid executive-dashboard"><header class="executive-head"><div><span class="eyebrow">PANEL EJECUTIVO</span><h2>Resumen de la plataforma</h2><p>Indicadores actuales de usuarios, docentes y recursos publicados.</p></div><div class="executive-actions"><span class="dashboard-date">DATOS EN TIEMPO REAL</span><div><a class="btn btn-manual" href="<?=url("/assets/docs/manual-administrador-ruta-docente.pdf")?>" download><span>↓</span> Manual administrador</a><a class="btn btn-brand" href="<?=url("/admin/usuarios/formulario")?>">+ Nuevo usuario</a></div></div></header><section class="kpi-grid"><?php foreach([['Usuarios',$totalUsers,'Cuentas registradas','U','purple','/admin/usuarios'],['Docentes',$teachers,$teacherPct.'% del total','D','green','/admin/usuarios'],['Tests',$tests,'Evaluaciones disponibles','T','yellow','/admin/tests'],['Talleres asincrónicos',$tabulators,'Herramientas registradas','▦','blue','/admin/talleres-asincronicos']] as $k):?><a class="kpi-card" href="<?=url($k[5])?>"><div class="kpi-top"><span class="kpi-icon <?=$k[4]?>"><?=$k[3]?></span><span class="kpi-link">↗</span></div><strong><?=$k[1]?></strong><h3><?=$k[0]?></h3><p><?=$k[2]?></p></a><?php endforeach;?></section><div class="dashboard-analysis-grid"><section class="analytics-card users-chart-card"><header><div><span class="analytics-kicker">COMPOSICIÓN</span><h3>Distribución de usuarios</h3></div><a href="<?=url('/admin/usuarios')?>">Ver usuarios →</a></header><div class="donut-content"><div class="donut-chart" style="--value:<?=$teacherPct?>"><div><strong><?=$teacherPct?>%</strong><span>docentes</span></div></div><div class="chart-legend"><div><i class="legend-purple"></i><p><span>Docentes</span><strong><?=$teachers?></strong></p></div><div><i class="legend-slate"></i><p><span>Administración</span><strong><?=$adminUsers?></strong></p></div><small>Distribución según el rol asignado a cada cuenta.</small></div></div></section><section class="analytics-card content-chart-card"><header><div><span class="analytics-kicker">RECURSOS</span><h3>Contenido de la plataforma</h3></div><span class="analytics-total"><?=$totalResources?> total</span></header><div class="horizontal-metrics"><div><div class="metric-label"><span>Tests</span><strong><?=$tests?></strong></div><div class="metric-track"><i class="test-bar" style="width:<?=$testPct?>%"></i></div><small><?=$totalResources?$testPct:0?>% de los recursos</small></div><div><div class="metric-label"><span>Talleres asincrónicos</span><strong><?=$tabulators?></strong></div><div class="metric-track"><i class="tabulator-bar" style="width:<?=$totalResources?100-$testPct:0?>%"></i></div><small><?=$totalResources?100-$testPct:0?>% de los recursos</small></div></div><div class="resource-efficiency"><span>Promedio</span><strong><?=$resourcesPerTeacher?></strong><p>recursos por docente registrado</p></div></section></div><section class="operations-card"><header><div><span class="analytics-kicker">ACCESOS RÁPIDOS</span><h3>Gestión operativa</h3></div><span>Administra los módulos principales</span></header><div class="operations-grid"><?php foreach([['/admin/usuarios','U','Usuarios','Gestionar cuentas y permisos'],['/admin/tests','T','Tests','Administrar evaluaciones'],['/admin/talleres-asincronicos','▦','Talleres asincrónicos','Organizar herramientas'],['/admin/catalogos','C','Catálogos','Configurar valores del sistema']] as $q):?><a href="<?=url($q[0])?>"><span><?=$q[1]?></span><div><strong><?=$q[2]?></strong><small><?=$q[3]?></small></div><b>→</b></a><?php endforeach;?></div></section></main>
